// Canary báo giá: gọi POST /v1/quotes như một khách và kiểm kết quả có giá hợp lệ.
// Chạy trong runtime CloudWatch Synthetics syn-nodejs-puppeteer-13.1 trở lên: module do runtime cung cấp
// dùng namespace mới @aws/synthetics-puppeteer và @aws/synthetics-logger (thay 'Synthetics', 'SyntheticsLogger').
const synthetics = require('@aws/synthetics-puppeteer');
const log = require('@aws/synthetics-logger');

const validateQuote = async function (res) {
  return new Promise((resolve, reject) => {
    if (res.statusCode < 200 || res.statusCode > 299) {
      reject(new Error(`HTTP ${res.statusCode} ${res.statusMessage}`));
      return;
    }
    let body = '';
    res.on('data', (chunk) => { body += chunk; });
    res.on('end', () => {
      try {
        const quote = JSON.parse(body);
        if (!(quote.price > 0)) {
          reject(new Error('Báo giá không hợp lệ: thiếu price > 0'));
          return;
        }
        log.info(`Báo giá hợp lệ cho thành phố HCM`);
        resolve();
      } catch (e) {
        reject(new Error(`Phản hồi không phải JSON: ${e.message}`));
      }
    });
  });
};

const checkQuote = async function () {
  const payload = JSON.stringify({
    city: 'HCM',
    service: 'ride',
    pickup: { lat: 10.7769, lng: 106.7009 },
    dropoff: { lat: 10.8231, lng: 106.6297 },
  });

  const requestOptions = {
    hostname: process.env.TARGET_HOST || 'api.toinoi.example',
    method: 'POST',
    path: '/v1/quotes',
    port: 443,
    protocol: 'https:',
    body: payload,
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
      'User-Agent': synthetics.getCanaryUserAgentString(),
    },
  };

  // Từ runtime 11.0, các tuỳ chọn ghi header/body chỉ đặt ở cấu hình chung, không đặt theo từng step.
  synthetics.getConfiguration().setConfig({
    includeRequestHeaders: false,
    includeResponseHeaders: false,
    includeRequestBody: false,
    includeResponseBody: false,
  });

  await synthetics.executeHttpStep('quote', requestOptions, validateQuote, { continueOnHttpStepFailure: false });
};

exports.handler = async () => {
  return await checkQuote();
};
